# Golden-parity tests: the current (optimised) implementation must reproduce
# reference outputs generated by the PRE-optimisation baseline
# (branch `glm-notes` @ 4b09088, FlexRL-bench/rlib-old). The fixtures live in
# tests/testthat/golden/ and were produced once by review/generate-goldens.R
# (see that script for provenance and regeneration); the baseline package is
# NOT needed to run these tests.
#
# Tolerance rationale
# -------------------
# * Deterministic artifacts (candidate-pair sets, LLL/LLA/LLB, log_lik): the
#   two implementations compute identical formulas and the parity study
#   (review/PARITY-REPORT.md §B) measured max |diff| = 0 (bitwise) on every
#   state. 1e-10 leaves an order of magnitude of headroom for floating-point
#   summation-order effects across BLAS/R builds while still catching any real
#   kernel change (a wrong index or weight shows up at O(1)).
# * StEM seed clouds: the RNG streams differ between implementations BY DESIGN
#   (PERF-PLAN §5: pre-drawn uniforms, inverse-CDF, factorised sampleL), so
#   equality is impossible; the unit of comparison is the cloud. Each new seed
#   is checked against the stored baseline cloud's per-component mean/sd with
#   |z| <= 5 (mission tolerance; the parity study observed 2.8-3.6 across all
#   problems). The Delta (x > 0.5) link sets are compared through the Jaccard
#   overlap: the mean old-vs-new overlap must stay within 0.05 of the old-vs-old
#   reference (different baseline seeds), which is ~2.4x the largest deviation
#   observed in the parity study (0.021); per-pair or min-based checks would
#   flake because single-seed link sets vary by up to sd 0.12 within the
#   baseline itself.
# * Tiny-problem frequencies: two independent 10k-draw estimates of the same
#   13-cell posterior. Observed old-vs-new TV = 0.0186, i.e. MC noise level;
#   TV <= 0.05 (the suite's existing tolerance for one estimate against the
#   exact posterior) and the same max-cell 0.025 / TV 0.05 checks against the
#   exact posterior as test-exact-posterior.R.

gold <- test_path("golden")

test_that("golden fixtures are present and provenance is the baseline build", {
  expect_true(dir.exists(gold), info = "tests/testthat/golden/ missing: run review/generate-goldens.R against the baseline build")
  meta <- readRDS(file.path(gold, "meta.rds"))
  expect_identical(meta$variant, "old")
  expect_identical(meta$baseline_ref, "glm-notes @ 4b09088")
})

test_that("golden fixed states rebuild bit-identically under the current implementation", {
  for (id in GOLDEN_STATE_IDS) {
    st <- readRDS(file.path(gold, sprintf("state_%s.rds", id)))
    rebuilt <- golden_build_state(id, st$data)
    expect_identical(rebuilt$truepivsA, st$truepivsA, info = id)
    expect_identical(rebuilt$truepivsB, st$truepivsB, info = id)
    expect_identical(rebuilt$linksR, st$linksR, info = id)
    expect_identical(rebuilt$sumRowD, st$sumRowD, info = id)
    expect_identical(rebuilt$sumColD, st$sumColD, info = id)
    expect_identical(rebuilt$eta, st$eta, info = id)
    expect_identical(rebuilt$phi, st$phi, info = id)
    expect_identical(rebuilt$alpha, st$alpha, info = id)
  }
})

test_that("candidate-pair sets match the baseline string pipeline", {
  for (id in GOLDEN_STATE_IDS) {
    st <- readRDS(file.path(gold, sprintf("state_%s.rds", id)))
    pr <- readRDS(file.path(gold, sprintf("pairs_%s.rds", id)))
    PIVs_stable <- vapply(st$data$PIVs_config, function(x) x$dynamics != "structured", logical(1))
    # canonical (i, j) sort: only the SET is contractual, not the row order
    sel_new <- golden_sort_pairs(golden_candidate_pairs(st$truepivsA, st$truepivsB, PIVs_stable))
    expect_identical(sel_new, pr$select_sorted,
                     info = sprintf("%s: %d baseline pairs vs %d current pairs", id, pr$n_pairs, nrow(sel_new)))
  }
})

test_that("likelihood values on the fixed states reproduce the baseline (<= 1e-10)", {
  for (id in GOLDEN_STATE_IDS) {
    st <- readRDS(file.path(gold, sprintf("state_%s.rds", id)))
    lk <- readRDS(file.path(gold, sprintf("likelihood_%s.rds", id)))
    art <- golden_capture_artifacts(golden_build_state(id, st$data))
    # LLL aligned by (iA, iB) pair: the implementations order candidate pairs
    # differently by design (see helper-golden.R)
    ko <- paste(lk$LLL_pairs$iA, lk$LLL_pairs$iB, sep = "_")
    kn <- paste(art$LLL_pairs$iA, art$LLL_pairs$iB, sep = "_")
    expect_setequal(ko, kn, info = id)
    dLLL <- max(abs(lk$LLL_pairs$LLL - art$LLL_pairs$LLL[match(ko, kn)]))
    dLLA <- max(abs(lk$LLA - art$LLA))
    dLLB <- max(abs(lk$LLB - art$LLB))
    expect_lte(dLLL, 1e-10,
               info = sprintf("%s: max|dLLL| = %.3g (baseline vs current, aligned by pair)", id, dLLL))
    expect_lte(dLLA, 1e-10, info = sprintf("%s: max|dLLA| = %.3g", id, dLLA))
    expect_lte(dLLB, 1e-10, info = sprintf("%s: max|dLLB| = %.3g", id, dLLB))
    # state log-likelihood: baseline internal value, baseline log_lik() and the
    # current implementation's log_lik() must agree
    d0 <- abs(lk$ll0_sparse - art$ll0_sparse)
    expect_lte(d0, 1e-10, info = sprintf("%s: |d log_lik| = %.3g", id, d0))
    if (!is.null(lk$ll0_internal)) {
      d0i <- abs(lk$ll0_internal - art$ll0_sparse)
      expect_lte(d0i, 1e-10, info = sprintf("%s: |d log_lik internal| = %.3g", id, d0i))
    }
  }
})

test_that("StEM seed clouds reproduce the baseline cloud (z <= 5; Delta Jaccard)", {
  pid_state <- c(std = "std_links", shiwreg = "shiwreg_links",
                 nltcs = "nltcs_links", shiwfull = "shiwfull_links")
  for (pid in names(pid_state)) {
    gc <- readRDS(file.path(gold, sprintf("stem_cloud_%s.rds", pid)))
    st <- readRDS(file.path(gold, sprintf("state_%s.rds", pid_state[[pid]])))
    problem <- c(list(prep = st$data, model_spec = gc$problem$model_spec), gc$problem[c("StEM_iter", "StEM_burnin", "gibbs_iter", "gibbs_burnin", "n_post_sample")])
    cn <- golden_run_cloud(problem)
    zs <- golden_zstats(golden_cloud_params(gc$cloud), golden_cloud_params(cn))
    zmax <- max(zs$new_vs_old)
    worst <- names(which.max(zs$new_vs_old))
    expect_lte(
      zmax, 5,
      info = sprintf(
        "%s: max|z| new-vs-baseline-cloud = %.2f (component %s); per-component: %s",
        pid, zmax, worst,
        paste(sprintf("%s=%.2f", names(zs$new_vs_old), zs$new_vs_old), collapse = ", ")
      )
    )
    # Delta (x > 0.5) link sets: old-vs-old (different baseline seeds) is the
    # reference distribution for seed noise; the swap must be indistinguishable
    jo <- c()
    for (a in seq_along(gc$cloud)) for (b in seq_len(a - 1L)) {
      jo <- c(jo, golden_jaccard(gc$cloud[[a]]$links, gc$cloud[[b]]$links))
    }
    jn <- c()
    for (a in gc$cloud) for (b in cn) jn <- c(jn, golden_jaccard(a$links, b$links))
    expect_lte(
      abs(mean(jn) - mean(jo)), 0.05,
      info = sprintf(
        "%s: Delta Jaccard old-vs-old mean %.3f (sd %.3f, min %.3f) vs old-vs-new mean %.3f (sd %.3f, min %.3f)",
        pid, mean(jo), stats::sd(jo), min(jo), mean(jn), stats::sd(jn), min(jn)
      )
    )
  }
})

test_that("tiny-problem frequencies match the baseline goldens and the exact posterior", {
  set.seed(2024) # same seed as the golden generation and test-exact-posterior.R
  freq <- tiny_gibbs_frequencies(n_sweeps = 30000, thin = 3L)
  gold_freq <- readRDS(file.path(gold, "tiny_frequencies.rds"))
  tv_gn <- golden_tv(freq, gold_freq)
  expect_lte(
    tv_gn, 0.05,
    info = sprintf(
      "TV(new, baseline-golden) = %.4f (parity study observed 0.0186; both are 10k-draw MC estimates)",
      tv_gn
    )
  )
  exact <- tiny_exact_posterior()
  emp <- golden_tiny_empirical(freq)
  tv_e <- 0.5 * sum(abs(emp - exact))
  expect_lte(max(abs(emp - exact)), 0.025,
             info = sprintf("max per-configuration deviation vs exact posterior = %.4f", max(abs(emp - exact))))
  expect_lte(tv_e, 0.05, info = sprintf("TV vs exact posterior = %.4f", tv_e))
})
